use vstd::prelude::*;

verus! {
    fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> (result: Vec<T>)
        requires
            dst.len() == src.len() && src.len() == mask.len(),
        ensures
            result.len() == dst.len(),
            forall|i: nat| 0 <= i < result.len() ==> 
                (mask[i as usize] ==> result[i as usize] == src[i as usize]) &&
                (!mask[i as usize] ==> result[i as usize] == dst[i as usize]),
    {
        let n = dst.len() as nat;
        let mut result: Vec<T> = Vec::new();
        result.resize(n as usize, dst[0]); // Initialize result with default values

        let mut i: nat = 0;
        while i < n
            invariant
                0 <= i <= n,
                result.len() == dst.len(),
                forall|j: nat| 0 <= j < i ==> 
                    (mask[j as usize] ==> result[j as usize] == src[j as usize]) &&
                    (!mask[j as usize] ==> result[j as usize] == dst[j as usize]),
            decreases n - i,
        {
            if mask[i as usize] {
                result[i as usize] = src[i as usize];
            } else {
                result[i as usize] = dst[i as usize];
            }
            i = i + 1;
        }
        result
    }
}
